def update_file(path, repls):
    with io.open(path, "r", encoding="utf-8") as f:
        txt = f.read()
    for old, new in repls:
        if old not in txt:
            print("WARN: not found in %s: %r" % (path, old[:60]))
            continue
        txt = txt.replace(old, new)
    with io.open(path, "w", encoding="utf-8") as f:
        f.write(txt)
    print("updated", path)

